<?php
namespace Tests\Feature;
use App\Models\User;
use App\Services\{VoiceAnswering,TwilioVoiceCalling,TwilioVoiceConnection,VoiceFollowups,VoiceEligibility,CadenceReentry,JourneyReports};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Http,File};
use Illuminate\Support\Str;
use Tests\TestCase;
use Twilio\Security\RequestValidator;
class VoiceAnsweringTest extends TestCase {
 use RefreshDatabase;
 private User $user;private int $contact;private int $campaign;private array $settings;private string $root;
 private string $parent='CA11111111111111111111111111111111';private string $child='CA22222222222222222222222222222222';
 protected function setUp():void {parent::setUp();Http::preventStrayRequests();$this->travelTo(now()->setDate(2026,10,12)->setTime(15,0));
  $this->root=sys_get_temp_dir().'/ma-amd-'.Str::uuid();config(['speech_test.root'=>$this->root,'twilio_voice_test'=>['account_sid'=>'AC'.str_repeat('1',32),'api_key'=>'SK'.str_repeat('2',32),'api_secret'=>'fixture-secret','auth_token'=>'fixture-signature','application_sid'=>'AP'.str_repeat('3',32),'caller_id'=>'+551130000001','edge'=>'sao-paulo','enabled'=>true]]);
  $this->user=User::factory()->create();$this->user->forceFill(['voice_workspace_id'=>1,'voice_role'=>'admin'])->save();$this->actingAs($this->user);
  $this->contact=DB::table('voice_contacts')->insertGetId(['workspace_id'=>1,'name'=>'QA','phone'=>'+5511999990001','original_phone'=>'+5511999990001','source'=>'QA','consent'=>true,'consent_evidence'=>'Fixture']);
  $this->settings=['mode'=>'preview','business_number'=>'+551130000001','number_mode'=>'separate','timezone'=>'UTC','days'=>[1,2,3,4,5,6,7],'start_time'=>'00:00','end_time'=>'23:59','max_attempts'=>5,'retry_minutes'=>1,'concurrency'=>1,'whatsapp_enabled'=>true,'whatsapp_after'=>1,'whatsapp_delay'=>0,'whatsapp_delivery'=>'automatic','whatsapp_text'=>'Oi, {nome}!','whatsapp_variables'=>[]];
  $this->campaign=DB::table('voice_campaigns')->insertGetId(['workspace_id'=>1,'name'=>'AMD QA','status'=>'testing','revision'=>1,'followup_revision'=>1,'settings'=>json_encode($this->settings),'created_at'=>now(),'updated_at'=>now()]);DB::table('voice_members')->insert(['campaign_id'=>$this->campaign,'contact_id'=>$this->contact]);
 }
 protected function tearDown():void {File::deleteDirectory($this->root);parent::tearDown();}
 private function callRow(array $extra=[]):string {$this->child='CA'.bin2hex(random_bytes(16));$this->parent='CA'.bin2hex(random_bytes(16));$id=(string)Str::uuid();DB::table('voice_outbound_calls')->insert($extra+['id'=>$id,'workspace_id'=>1,'user_id'=>$this->user->id,'contact_id'=>$this->contact,'campaign_id'=>$this->campaign,'campaign_revision'=>1,'idempotency_key'=>(string)Str::uuid(),'request_hash'=>str_repeat('a',64),'grant_hash'=>hash('sha256',$id),'configuration_hash'=>str_repeat('c',64),'method'=>'programmable_voice','provider_account'=>config('twilio_voice_test.account_sid'),'channel_id'=>$this->parent,'provider_child_sid'=>$this->child,'destination'=>'+5511999990001','caller_id'=>'+551130000001','status'=>'answered','amd_mode'=>'detect','answer_classification'=>'pending','max_seconds'=>120,'ring_seconds'=>30,'consent_evidence'=>'Fixture','grant_expires_at'=>now(),'deadline_at'=>now()->addMinutes(3),'started_at'=>now()->subSeconds(10),'answered_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return $id;}
 private function hook(string $path,array $d,bool $signed=true){$d=['AccountSid'=>config('twilio_voice_test.account_sid')]+$d;$sig=(new RequestValidator(config('twilio_voice_test.auth_token')))->computeSignature(TwilioVoiceConnection::BASE.$path,$d);return $this->call('POST','/callbacks/twilio/voice'.$path,$d,[],[],['CONTENT_TYPE'=>'application/x-www-form-urlencoded','HTTP_ACCEPT'=>'application/json','HTTP_X_TWILIO_SIGNATURE'=>$signed?$sig:'bad'],http_build_query($d));}
 private function amd(string $id,string $by='human'){return $this->hook('/amd/'.$id,['CallSid'=>$this->child,'AnsweredBy'=>$by,'MachineDetectionDuration'=>'3500']);}
 private function finish(string $id){return $this->hook('/status/'.$id,['CallSid'=>$this->child,'ParentCallSid'=>$this->parent,'CallStatus'=>'completed','CallDuration'=>'10']);}
 private function row(string $id):object{return DB::table('voice_outbound_calls')->find($id);}
 private function asset(int $w=1):string {$id=(string)Str::uuid();DB::table('speech_assets')->insert(['id'=>$id,'workspace_id'=>$w,'user_id'=>$this->user->id,'name'=>'Recado QA','body'=>'Aqui é a equipe. Entraremos em contato.','voice'=>'pf_dora','speed'=>1,'fingerprint'=>str_repeat('a',64),'status'=>'ready','duration'=>5,'expires_at'=>now()->addDays(2),'created_at'=>now(),'updated_at'=>now()]);$dir=$this->root.'/'.$w.'/'.$id;File::ensureDirectoryExists($dir);foreach(['wav','mp3']as $f)file_put_contents($dir.'/audio.'.$f,str_repeat('x',100));return $id;}
 private function messageCall(array $extra=[]):string {return $this->callRow($extra+['amd_mode'=>'message','voicemail_asset_id'=>$this->asset(),'voicemail_status'=>'waiting']);}
 public function test_signed_result_is_bound_to_proven_child_even_if_amd_arrives_first():void {$id=$this->callRow(['provider_child_sid'=>null]);$this->hook('/amd/'.$id,['CallSid'=>$this->child,'AnsweredBy'=>'human'],false)->assertForbidden();$this->amd($id)->assertNoContent();$this->assertSame('pending',$this->row($id)->answer_classification);$this->finish($id)->assertNoContent();$this->assertSame('human',$this->row($id)->answer_classification);$this->hook('/amd/'.$id,['CallSid'=>'CA'.str_repeat('3',32),'AnsweredBy'=>'machine_start'])->assertForbidden();Http::assertNothingSent();}
 public function test_conflicting_duplicate_callbacks_preserve_first_classification():void {$id=$this->callRow();$this->amd($id)->assertNoContent();$this->amd($id)->assertNoContent();$this->amd($id,'machine_start')->assertNoContent();$this->assertSame('human',$this->row($id)->answer_classification);$this->assertDatabaseCount('voice_answer_events',2);Http::assertNothingSent();}
 public function test_technical_answer_does_not_end_run_until_human_classification():void {DB::table('voice_campaigns')->where('id',$this->campaign)->update(['settings'=>json_encode($this->settings+['reentry'=>CadenceReentry::DEFAULTS])]);$c=DB::table('voice_campaigns')->find($this->campaign);app(CadenceReentry::class)->sync($c);$run=app(CadenceReentry::class)->current($this->campaign,$this->contact);$id=$this->callRow(['run_id'=>$run->id]);app(VoiceFollowups::class)->observe($id);$this->assertSame('active',DB::table('voice_cadence_runs')->find($run->id)->status);$this->amd($id)->assertNoContent();$this->assertSame('answered',DB::table('voice_cadence_runs')->find($run->id)->exit_reason);}
 public function test_unknown_holds_run_and_retry_after_terminal_network_event():void {DB::table('voice_campaigns')->where('id',$this->campaign)->update(['settings'=>json_encode(array_replace($this->settings,['max_attempts'=>1,'reentry'=>CadenceReentry::DEFAULTS]))]);$c=DB::table('voice_campaigns')->find($this->campaign);app(CadenceReentry::class)->sync($c);$run=app(CadenceReentry::class)->current($this->campaign,$this->contact);$id=$this->callRow(['run_id'=>$run->id]);$this->amd($id,'unknown')->assertNoContent();$this->finish($id)->assertNoContent();app(CadenceReentry::class)->reconcile(DB::table('voice_cadence_runs')->find($run->id));$this->assertSame('active',DB::table('voice_cadence_runs')->find($run->id)->status);$this->assertDatabaseCount('voice_followups',0);$this->assertTrue(DB::table('voice_outbound_calls')->whereRaw(VoiceAnswering::reviewSql())->exists());}
 public function test_machine_counts_for_whatsapp_only_with_explicit_opt_in_and_after_hangup():void {$id=$this->callRow();$this->amd($id,'machine_start')->assertNoContent();$this->finish($id)->assertNoContent();$this->assertDatabaseCount('voice_followups',0);$second=$this->callRow(['amd_count_machine'=>true]);$this->amd($second,'machine_start')->assertNoContent();$this->assertDatabaseCount('voice_followups',0);$this->finish($second)->assertNoContent();$this->assertDatabaseCount('voice_followups',1);$this->finish($second)->assertNoContent();$this->assertDatabaseCount('voice_followups',1);Http::assertNothingSent();}
 public function test_late_human_cancels_pending_followup_and_unknown_prevents_send():void {$miss=$this->callRow(['amd_mode'=>'off','answer_classification'=>'not_requested','status'=>'no_answer','answered_at'=>null,'ended_at'=>now(),'capacity_released_at'=>now()]);app(VoiceFollowups::class)->observe($miss);$this->assertDatabaseCount('voice_followups',1);$id=$this->callRow(['status'=>'completed','ended_at'=>now(),'capacity_released_at'=>now()]);$this->amd($id)->assertNoContent();$this->assertDatabaseHas('voice_followups',['status'=>'cancelled']);Http::assertNothingSent();}
 public function test_beep_updates_only_existing_child_once_and_plays_once():void {$id=$this->messageCall();Http::fake(['https://api.twilio.com/*'=>Http::response(['sid'=>$this->child])]);$this->amd($id,'machine_end_beep')->assertNoContent();$this->amd($id,'machine_end_beep')->assertNoContent();Http::assertSentCount(1);Http::assertSent(fn($r)=>$r->method()==='POST'&&str_ends_with($r->url(),'/Calls/'.$this->child.'.json')&&$r['Url']===TwilioVoiceConnection::BASE.'/voicemail/'.$id);$this->assertSame('instructed',$this->row($id)->voicemail_status);$this->hook('/voicemail/'.$id,['CallSid'=>$this->child])->assertOk()->assertSee('<Play>',false)->assertSee('signature=',false);$this->hook('/voicemail/'.$id,['CallSid'=>$this->child])->assertOk()->assertDontSee('<Play>',false);$this->hook('/finish/'.$id,['CallSid'=>$this->parent,'DialCallSid'=>$this->child,'DialCallStatus'=>'completed'])->assertOk();$this->assertNull($this->row($id)->capacity_released_at);$this->finish($id)->assertNoContent();$this->assertSame('unconfirmed',$this->row($id)->voicemail_status);$this->hook('/voicemail-finished/'.$id,['CallSid'=>$this->child])->assertOk();$this->assertSame('played',$this->row($id)->voicemail_status);$this->assertNotNull($this->row($id)->capacity_released_at);}
 public function test_ambiguous_provider_write_is_never_retried():void {$id=$this->messageCall();Http::fake(function(){throw new \Illuminate\Http\Client\ConnectionException('timeout');});$this->amd($id,'machine_end_beep')->assertNoContent();$this->assertSame('unconfirmed',$this->row($id)->voicemail_status);Http::swap(new \Illuminate\Http\Client\Factory);Http::preventStrayRequests();$this->amd($id,'machine_end_beep')->assertNoContent();app(VoiceAnswering::class)->deliver($id);Http::assertNothingSent();}
 public function test_no_beep_or_ended_call_does_not_play_or_redirect():void {foreach(['machine_end_silence','machine_end_other','machine_start','human','fax','unknown']as $by){$id=$this->messageCall();$this->amd($id,$by)->assertNoContent();$this->assertSame('skipped',$this->row($id)->voicemail_status);}$id=$this->messageCall(['status'=>'completed','ended_at'=>now(),'capacity_released_at'=>now()]);$this->amd($id,'machine_end_beep')->assertNoContent();$this->assertSame('skipped',$this->row($id)->voicemail_status);Http::assertNothingSent();}
 public function test_revoked_consent_or_paused_campaign_prevents_redirect():void {$id=$this->messageCall();DB::table('voice_campaigns')->where('id',$this->campaign)->update(['status'=>'paused']);$this->amd($id,'machine_end_beep')->assertNoContent();$this->assertSame('skipped',$this->row($id)->voicemail_status);Http::assertNothingSent();}
 public function test_expired_audio_and_cross_workspace_asset_are_rejected():void {$a=$this->asset(2);try{app(VoiceAnswering::class)->validate(1,['mode'=>'message','audio_asset_id'=>$a,'audio_generic_confirmed'=>true,'count_machine_as_missed'=>false]);$this->fail('Workspace');}catch(\Illuminate\Database\Eloquent\ModelNotFoundException|\Illuminate\Database\RecordNotFoundException $e){$this->assertTrue(true);} $a=$this->asset();DB::table('speech_assets')->where('id',$a)->update(['expires_at'=>now()->addMinutes(5)]);$this->getJson('/api/voice/speech/ready')->assertOk()->assertJsonCount(0,'assets');}
 public function test_missing_detection_times_out_to_unknown_without_releasing_capacity():void {$id=$this->callRow(['started_at'=>now()->subSeconds(100)]);app(VoiceAnswering::class)->expire();$this->assertSame('unknown',$this->row($id)->answer_classification);$this->assertNull($this->row($id)->capacity_released_at);$this->amd($id)->assertNoContent();$this->assertSame('human',$this->row($id)->answer_classification);}
 public function test_human_review_wins_over_late_machine_detection():void {$id=$this->callRow(['status'=>'completed','ended_at'=>now(),'capacity_released_at'=>now()]);DB::table('voice_outbound_calls')->where('id',$id)->update(['human_confirmed'=>true]);app(VoiceAnswering::class)->reviewed($this->row($id),(object)['human'=>true,'code'=>'contacted']);$this->amd($id,'machine_start')->assertNoContent();$this->assertSame('human',$this->row($id)->answer_classification);}
 public function test_dashboard_differentiates_humans_machines_and_legacy_without_rewriting_history():void {$human=$this->callRow();$this->amd($human)->assertNoContent();$machine=$this->callRow();$this->amd($machine,'machine_start')->assertNoContent();$this->callRow(['amd_mode'=>'off','answer_classification'=>'not_requested']);$this->callRow();$f=['from'=>'2026-10-12','to'=>'2026-10-12','campaign_id'=>$this->campaign];$d=app(JourneyReports::class)->dashboard(1,$f);foreach(['human_answered','machine','answer_unknown','answer_unverified']as $key)$this->assertSame(1,$d['summary'][$key]);$this->assertSame(4,$d['summary']['answered']);$rows=app(JourneyReports::class)->details(1,$f+['metric'=>'machine']);$this->assertSame($machine,$rows['rows']->items()[0]->id);$this->assertSame(0,app(JourneyReports::class)->dashboard(2,$f)['summary']['calls']);}
 public function test_disabled_defaults_no_amd_and_sip_is_rejected_when_enabled():void {$s=app(VoiceAnswering::class);$this->assertSame([],$s->snapshot(1,'sip_trunk',[]));$this->assertSame([],$s->options($this->row($this->callRow(['amd_mode'=>'off']))));$opts=$s->options($this->row($this->callRow()));$this->assertSame('Enable',$opts['machineDetection']);try{$s->snapshot(1,'sip_trunk',['answering'=>array_replace(VoiceAnswering::DEFAULTS,['mode'=>'detect'])]);$this->fail('SIP unsupported');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(422,$e->getStatusCode());}Http::assertNothingSent();}
}
